/**
 * Checks that validation correctly stops when finding a circular
 * dependency.
 */
@Test
public void testAutoreferringBean() {
    Person p1 = new Person();
    p1.name = "too-long-name";
    p1.sibling = p1;
    Set<ConstraintViolation<Person>> violations = validator.validate(p1);
